python3 - <<'EOF'
import json, re
files=['7c6fa1c3-be62-4bed-a685-8944a3de6e05','9d2b7dee-a736-4c53-8e10-447db3c2052f','6b6694c2-be10-47c3-bef0-d94a078d7e78','f8dd62b0-f8b3-4707-b06a-8420979599d2','e8928553-e624-41d1-b476-e99ae92f0cdb']
base='/home/hal/.claude/projects/-home-hal-dev-interp-dm-hack/'
rows=[]
seen=set()
for fn in files:
    for line in open(base+fn+'.jsonl'):
        try: e=json.loads(line)
        except: continue
        if e.get('type')!='assistant' or e.get('isSidechain'): continue
        ts=e.get('timestamp','')
        for c in e.get('message',{}).get('content',[]):
            if isinstance(c,dict) and c.get('type')=='text':
                t=c['text']
                m=re.search(r'(a question forms|second representation|no-solutions|five mismatch|question formation|pairing.*counterpart|two co-present)', t, re.I)
                if m and ts[:16] not in seen:
                    seen.add(ts[:16]); i=m.start()
                    rows.append((ts,fn[:8],t[max(0,i-60):i+260]))
rows.sort()
print("FORMATION-criteria passages:", len(rows))
for ts,fn,s in rows[:8]: print(f"\n== [{ts[:16]} {fn}] ==\n{s}")
EOF
